    let capacity = bin_capacity.max(1) as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let is_new = (bin_residual == bin_capacity) as u8 as f64;

    let progress = if total_items > 0 {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    } else {
        1.0
    };

    let mean_gap = (mean_residual - residual).clamp(-capacity, capacity);
    score += 0.42 * mean_gap;

    let tightness = (residual / capacity).clamp(0.0, 1.0);
    let post_tightness = (post_residual as f64 / capacity).clamp(0.0, 1.0);
    score += 16.0 * tightness * (1.0 - post_tightness);

    let utilization = 1.0 - residual / capacity;
    let curvature = (utilization - 0.5).abs();
    score += 5.0 * (curvature - 0.5).powi(2);

    if next_item_size > 0 {
        let next = next_item_size as f64;
        let next_fits = (post_residual as f64 + 0.5 >= next) as u8 as f64;
        let next_residual = (post_residual as f64 - next).max(0.0);
