        score += 0.8 * progress * (fitting_bins_count as f64).ln();
    }

    score += 0.012 * (open_bins_count as f64).sqrt();
    score -= 0.006 * (open_bins_count as f64) * progress;

    if is_new > 0.5 {
        score += 8.0 + 12.0 * progress;
        if post_residual <= item {
            score -= 6.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
