            score -= 18.0;
        } else {
            score -= 2.0;
        }
    } else {
        // Reward consuming space, especially on a bin whose remaining capacity
        // is small relative to the average open bin.
        let residual_penalty = 1.0 + 0.045 * post_residual as f64;
        score *= residual_penalty;

        let scarcity = (mean - post_residual as f64).max(0.0);
        score -= 1.25 * scarcity;

        // Prefer a tight fit, while allowing a later item to use the residue.
        let fit_gap = (bin_residual as f64 - item).max(0.0);
        score += 0.018 * fit_gap;

        // Two-step lookahead: strongly reward a residue that can accommodate
        // the next item, and penalize dead residues otherwise.
