    };
    let capacity = bin_capacity.max(1) as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let mean = mean_residual.max(0.0).min(capacity);
    let normalized_post = (post / capacity).clamp(0.0, 1.0);
    let normalized_mean = (mean / capacity).clamp(0.0, 1.0);
    let fit_ratio = (residual / capacity).clamp(0.0, 1.0);
    let pressure = (open_bins_count as f64).sqrt();
    let next = next_item_size as f64;
    let scarcity = if fitting_bins_count == 0 {
        1.0
    } else {
        (1.0 / fitting_bins_count as f64).sqrt()
    };

    score += 42.0 * progress * normalized_post;
    score -= 30.0 * progress * fit_ratio * fit_ratio;
    score -= 18.0 * (1.0 - progress) * normalized_mean;
    score += 9.0 * scarcity * (post / capacity);
    score -= 7.0 * scarcity * pressure * (item / capacity);
    score += 0.08 * pressure * item * (1.0 - normalized_post);
    score -= 4.0 * next * progress * (post / capacity);
    score
}
